		errPrefix:   "",
	},
	{
		description: "valid limits 10-99",
		fmin:        10,
		fmax:        99,
		pmin:        Product{121, [][2]int{{11, 11}}},
		pmax:        Product{9009, [][2]int{{91, 99}}},
		errPrefix:   "",
	},
	{
