			name: "singleton",
			tree: New("x"),
		},
		{
			name: "parent and one sibling",
			tree: New("parent", New("x"), New("sibling")),
		},
		{
			name: "parent and kids",
			tree: New("parent", New("x", New("kid-0"), New("kid-1"))),
		},
	}
